```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Channels;
using System.Threading.Tasks;

namespace TransportManagementSystem
{
    #region --- SHARED MODELS & CONTRACTS ---

    public record TelemetryReading(
        string VehicleId, 
        string RouteSegmentId, 
        double SpeedKmh, 
        double Latitude, 
        double Longitude, 
        DateTime Timestamp
    );

    public record SpeedAnomaly(
        string VehicleId, 
        List<double> RecordedSpeeds, 
        List<DateTime> Timestamps, 
        string Message
    );

    public record TripCompletion(
        string TripId, 
        string VehicleId, 
        List<string> TraveledSegments, 
        double TotalDistanceKm, 
        DateTime EndTime
    );

    public record Invoice(
        string InvoiceId, 
        string TripId, 
        string VehicleId, 
        double CalculatedToll, 
        DateTime BilledAt
    );

    #endregion

    #region --- MODULE 1: FLEET TELEMETRY TRACKER ---

    public class TelemetryTracker
    {
        private readonly ConcurrentDictionary<string, List<TelemetryReading>> _vehicleHistory = new();
        private readonly int _consecutiveViolationLimit;
        private readonly double _speedThresholdKmh;

        public event EventHandler<SpeedAnomaly>? OnSpeedAnomalyDetected;
        public event EventHandler<TelemetryReading>? OnTelemetryProcessed;

        public TelemetryTracker(double speedThresholdKmh = 110.0, int consecutiveViolationLimit = 3)
        {
            _speedThresholdKmh = speedThresholdKmh;
            _consecutiveViolationLimit = consecutiveViolationLimit;
        }

        public void ProcessTelemetry(TelemetryReading reading)
        {
            // Signal streaming ingestion event to downstream bridge/subsystems
            OnTelemetryProcessed?.Invoke(this, reading);

            _vehicleHistory.AddOrUpdate(
                reading.VehicleId,
                _ => new List<TelemetryReading> { reading },
                (_, historyList) =>
                {
                    lock (historyList)
                    {
                        historyList.Add(reading);

                        // Keep a sliding window size matching the trigger parameters
                        if (historyList.Count > _consecutiveViolationLimit)
                        {
                            historyList.RemoveAt(0);
                        }

                        // Evaluate sliding window for consecutive speeding violations
                        if (historyList.Count == _consecutiveViolationLimit && 
                            historyList.All(r => r.SpeedKmh > _speedThresholdKmh))
                        {
                            var anomaly = new SpeedAnomaly(
                                VehicleId: reading.VehicleId,
                                RecordedSpeeds: historyList.Select(h => h.SpeedKmh).ToList(),
                                Timestamps: historyList.Select(h => h.Timestamp).ToList(),
                                Message: $"Speed violation: {historyList.Count} consecutive readings exceeded speed limit of {_speedThresholdKmh} km/h."
                            );

                            ThreadPool.QueueUserWorkItem(_ => OnSpeedAnomalyDetected?.Invoke(this, anomaly));
                        }
                    }
                    return historyList;
                }
            );
        }
    }

    #endregion

    #region --- MODULE 2: ROUTE OPTIMIZATION ENGINE ---

    public class RouteOptimizer
    {
        private readonly ReaderWriterLockSlim _graphLock = new();
        private readonly Dictionary<string, List<RouteSegment>> _adjacencyList = new();

        public class RouteSegment
        {
            public string Source { get; }
            public string Target { get; }
            public double BaseDistanceKm { get; }
            public double WeightMultiplier { get; set; } = 1.0;
            public double DynamicWeight => BaseDistanceKm * WeightMultiplier;

            public RouteSegment(string source, string target, double baseDistanceKm)
            {
                Source = source;
                Target = target;
                BaseDistanceKm = baseDistanceKm;
            }
        }

        public void AddOrUpdateSegment(string source, string target, double distanceKm)
        {
            _graphLock.EnterWriteLock();
            try
            {
                if (!_adjacencyList.TryGetValue(source, out var edges))
                {
                    edges = new List<RouteSegment>();
                    _adjacencyList[source] = edges;
                }

                var existingSegment = edges.FirstOrDefault(e => e.Target == target);
                if (existingSegment != null)
                {
                    edges.Remove(existingSegment);
                }

                edges.Add(new RouteSegment(source, target, distanceKm));

                // Guarantee target node also exists in graph representation as index entry
                if (!_adjacencyList.ContainsKey(target))
                {
                    _adjacencyList[target] = new List<RouteSegment>();
                }
            }
            finally
            {
                _graphLock.ExitWriteLock();
            }
        }

        public bool UpdateSegmentWeight(string source, string target, double congestionMultiplier)
        {
            _graphLock.EnterWriteLock();
            try
            {
                if (_adjacencyList.TryGetValue(source, out var edges))
                {
                    var edge = edges.FirstOrDefault(e => e.Target == target);
                    if (edge != null)
                    {
                        edge.WeightMultiplier = Math.Clamp(congestionMultiplier, 1.0, 10.0);
                        return true;
                    }
                }
                return false;
            }
            finally
            {
                _graphLock.ExitWriteLock();
            }
        }

        public (List<string> Path, double TotalCost) CalculateOptimalPath(string startNode, string targetNode)
        {
            _graphLock.EnterReadLock();
            try
            {
                if (!_adjacencyList.ContainsKey(startNode) || !_adjacencyList.ContainsKey(targetNode))
                {
                    return (new List<string>(), double.PositiveInfinity);
                }

                var distances = new Dictionary<string, double>();
                var previousNodes = new Dictionary<string, string>();
                var priorityQueue = new PriorityQueue<string, double>();

                foreach (var node in _adjacencyList.Keys)
                {
                    distances[node] = double.PositiveInfinity;
                }

                distances[startNode] = 0.0;
                priorityQueue.Enqueue(startNode, 0.0);

                while (priorityQueue.Count > 0)
                {
                    var current = priorityQueue.Dequeue();

                    if (current == targetNode)
                        break;

                    if (!_adjacencyList.TryGetValue(current, out var segments))
                        continue;

                    foreach (var segment in segments)
                    {
                        double tentativeCost = distances[current] + segment.DynamicWeight;
                        if (tentativeCost < distances[segment.Target])
                        {
                            distances[segment.Target] = tentativeCost;
                            previousNodes[segment.Target] = current;
                            priorityQueue.Enqueue(segment.Target, tentativeCost);
                        }
                    }
                }

                if (!distances.TryGetValue(targetNode, out double finalDistance) || finalDistance == double.PositiveInfinity)
                {
                    return (new List<string>(), double.PositiveInfinity);
                }

                var path = new List<string>();
                string? step = targetNode;
                while (step != null)
                {
                    path.Insert(0, step);
                    previousNodes.TryGetValue(step, out step);
                }

                return (path, finalDistance);
            }
            finally
            {
                _graphLock.ExitReadLock();
            }
        }
    }

    #endregion

    #region --- MODULE 3: AUTOMATED BILLING & INVOICING ---

    public class BillingSubsystem
    {
        private readonly Channel<TripCompletion> _billingQueue;
        private readonly Action<Invoice> _invoicePublisher;
        private readonly CancellationTokenSource _cts = new();
        private Task? _processingWorker;

        public BillingSubsystem(Action<Invoice> invoicePublisher, int queueCapacity = 5000)
        {
            _invoicePublisher = invoicePublisher;

            // Set up a channel with a bounded capacity to enforce strict backpressure bounds
            _billingQueue = Channel.CreateBounded<TripCompletion>(new BoundedChannelOptions(queueCapacity)
            {
                FullMode = BoundedChannelFullMode.Wait,
                SingleReader = true,
                SingleWriter = false
            });
        }

        public void Start()
        {
            _processingWorker = Task.Run(() => ProcessInvoicesAsync(_cts.Token));
        }

        public async Task StopAsync()
        {
            _billingQueue.Writer.Complete();
            _cts.Cancel();
            if (_processingWorker != null)
            {
                try
                {
                    await _processingWorker;
                }
                catch (OperationCanceledException) { }
            }
        }

        public async Task SubmitTripForBillingAsync(TripCompletion trip)
        {
            await _billingQueue.Writer.WriteAsync(trip);
        }

        private async Task ProcessInvoicesAsync(CancellationToken cancellationToken)
        {
            var reader = _billingQueue.Reader;
            while (await reader.WaitToReadAsync(cancellationToken))
            {
                while (reader.TryRead(out var trip))
                {
                    try
                    {
                        // Dynamic calculation structure based on trip length and routing complexity
                        const double baseRatePerKm = 0.25; 
                        double structurePremium = trip.TraveledSegments.Count * 0.50;
                        double rawTotal = (trip.TotalDistanceKm * baseRatePerKm) + structurePremium;

                        // Simulate high-reliability tax calculations and database roundtrips
                        await Task.Delay(10, cancellationToken); 

                        var invoice = new Invoice(
                            InvoiceId: $"INV-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}",
                            TripId: trip.TripId,
                            VehicleId: trip.VehicleId,
                            CalculatedToll: Math.Round(rawTotal, 2),
                            BilledAt: DateTime.UtcNow
                        );

                        _invoicePublisher(invoice);
                    }
                    catch (Exception ex)
                    {
                        Console.ForegroundColor = ConsoleColor.Red;
                        Console.WriteLine($"[Billing Error] Failed to generate invoice for trip {trip.TripId}: {ex.Message}");
                        Console.ResetColor();
                    }
                }
            }
        }
    }

    #endregion

    #region --- INTEGRATION COMPONENT: COUPLING PIPELINE ---

    /// <summary>
    /// Acts as the decoupler and orchestration pipeline. Maps telemetry velocity reports (Module 1)
    /// to dynamic weight changes in the routing network (Module 2) to maintain dynamic traffic states.
    /// </summary>
    public class TelemetryRouteIntegrationBridge
    {
        private readonly RouteOptimizer _optimizer;
        private readonly ConcurrentDictionary<string, double> _nominalSpeeds = new();

        public TelemetryRouteIntegrationBridge(RouteOptimizer optimizer)
        {
            _optimizer = optimizer;

            // Expected normal freeway baseline speeds for target segments in graph definition
            _nominalSpeeds["A-B"] = 100.0;
            _nominalSpeeds["B-C"] = 90.0;
            _nominalSpeeds["C-D"] = 100.0;
            _nominalSpeeds["A-D"] = 110.0;
        }

        public void HandleTelemetryProcessed(object? sender, TelemetryReading reading)
        {
            if (!_nominalSpeeds.TryGetValue(reading.RouteSegmentId, out double nominalSpeed)) 
                return;

            // Congestion scales exponentially as actual speed drops below nominal segment capacity
            double speedRatio = nominalSpeed / Math.Max(reading.SpeedKmh, 5.0);
            double congestionMultiplier = Math.Clamp(speedRatio, 1.0, 8.0);

            string[] nodes = reading.RouteSegmentId.Split('-');
            if (nodes.Length == 2)
            {
                bool success = _optimizer.UpdateSegmentWeight(nodes[0], nodes[1], congestionMultiplier);
                if (success && congestionMultiplier > 1.2)
                {
                    Console.ForegroundColor = ConsoleColor.Yellow;
                    Console.WriteLine($"[Traffic Update] Dynamic Weight applied on {reading.RouteSegmentId}: Speed={reading.SpeedKmh:F1} km/h, Multiplier={congestionMultiplier:F2}x");
                    Console.ResetColor();
                }
            }
        }
    }

    #endregion

    #region --- SYSTEM DEMONSTRATION HARNESS ---

    public class Program
    {
        public static async Task Main()
        {
            Console.WriteLine("======================================================================");
            Console.WriteLine("      LAUNCHING MULTI-THREADED TRANSPORT MANAGEMENT SYSTEM             ");
            Console.WriteLine("======================================================================\n");

            // 1. Initialize Subsystem Modules
            var telemetryTracker = new TelemetryTracker(speedThresholdKmh: 110.0, consecutiveViolationLimit: 3);
            var routeOptimizer = new RouteOptimizer();
            var billingEngine = new BillingSubsystem(invoice =>
            {
                Console.ForegroundColor = ConsoleColor.Green;
                Console.WriteLine($"[Invoice Generated] ID: {invoice.InvoiceId} | Vehicle: {invoice.VehicleId} | Final Toll: ${invoice.CalculatedToll:F2} | Time: {invoice.BilledAt:HH:mm:ss.fff}");
                Console.ResetColor();
            });

            var integrationBridge = new TelemetryRouteIntegrationBridge(routeOptimizer);

            // Connect event pipeline out of Module 1 into our Integration Bridge
            telemetryTracker.OnTelemetryProcessed += integrationBridge.HandleTelemetryProcessed;

            // Handle speed anomalies
            telemetryTracker.OnSpeedAnomalyDetected += (sender, anomaly) =>
            {
                Console.ForegroundColor = ConsoleColor.Red;
                Console.WriteLine($"[SPEED ANOMALY] Vehicle {anomaly.VehicleId} exceeded limit across multiple continuous pings! Speeds: {string.Join(" km/h, ", anomaly.RecordedSpeeds)} km/h");
                Console.ResetColor();
            };

            billingEngine.Start();

            // 2. Initialize Graph Infrastructure Topology
            routeOptimizer.AddOrUpdateSegment("A", "B", distanceKm: 15.0);
            routeOptimizer.AddOrUpdateSegment("B", "C", distanceKm: 10.0);
            routeOptimizer.AddOrUpdateSegment("C", "D", distanceKm: 25.0);
            routeOptimizer.AddOrUpdateSegment("A", "D", distanceKm: 60.0); // High-speed route bypassing A-B-C-D

            // 3. Kick off Continuous Multi-Threaded Simulation
            using var cts = new CancellationTokenSource();

            // Thread A: Simulate GPS Telemetry Stream (Module 1)
            var telemetryGenerator = Task.Run(async () =>
            {
                string[] segments = { "A-B", "B-C", "C-D", "A-D" };
                string[] vehicles = { "TRK-001", "TRK-002", "TRK-003" };
                var random = new Random();

                while (!cts.Token.IsCancellationRequested)
                {
                    string vehicle = vehicles[random.Next(vehicles.Length)];
                    string segment = segments[random.Next(segments.Length)];

                    // Simulate random driving velocity - occasionally spike values to test speeding rules
                    double velocity = random.NextDouble() > 0.85 ? random.Next(120, 145) : random.Next(40, 95);

                    var read = new TelemetryReading(
                        VehicleId: vehicle,
                        RouteSegmentId: segment,
                        SpeedKmh: velocity,
                        Latitude: 37.7749 + (random.NextDouble() * 0.01),
                        Longitude: -122.4194 + (random.NextDouble() * 0.01),
                        Timestamp: DateTime.UtcNow
                    );

                    telemetryTracker.ProcessTelemetry(read);
                    await Task.Delay(250, cts.Token);
                }
            }, cts.Token);

            // Thread B: Simulate Continuous Dijkstra Query Requests against RouteOptimizer (Module 2)
            var routingServiceSimulator = Task.Run(async () =>
            {
                var random = new Random();
                while (!cts.Token.IsCancellationRequested)
                {
                    var (path, cost) = routeOptimizer.CalculateOptimalPath("A", "D");
                    Console.ForegroundColor = ConsoleColor.Cyan;
                    Console.WriteLine($"[Route calculation] Path: {string.Join(" -> ", path)} | Total Cost Weight: {cost:F2}");
                    Console.ResetColor();

                    await Task.Delay(800, cts.Token);
                }
            }, cts.Token);

            // Thread C: Submit Trip Deliveries continuously to the Dynamic Billing Subsystem (Module 3)
            var billingSimulator = Task.Run(async () =>
            {
                var random = new Random();
                int tripCounter = 1;
                while (!cts.Token.IsCancellationRequested)
                {
                    var trip = new TripCompletion(
                        TripId: $"TRIP-{tripCounter++:D4}",
                        VehicleId: $"TRK-{random.Next(100, 999)}",
                        TraveledSegments: new List<string> { "A", "B", "C", "D" },
                        TotalDistanceKm: 50.0 + (random.NextDouble() * 20.0),
                        EndTime: DateTime.UtcNow
                    );

                    await billingEngine.SubmitTripForBillingAsync(trip);
                    await Task.Delay(1200, cts.Token);
                }
            }, cts.Token);

            // Run system simulation for 8 seconds, then gracefully exit
            await Task.Delay(8000);

            Console.WriteLine("\n[System Shut Down Initiation] Cancelling tasks, flushing queues...");
            cts.Cancel();

            try
            {
                await Task.WhenAll(telemetryGenerator, routingServiceSimulator, billingSimulator);
            }
            catch (Exception) { /* catch cancellations */ }

            await billingEngine.StopAsync();
            Console.WriteLine("System successfully shut down.");
        }
    }

    #endregion
}
